package com.franco.desco.adapter.in.web.evaluation;import com.franco.desco.application.evaluation.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.evaluation.EvaluationModels;import org.springframework.stereotype.Component;import java.time.Instant;
@Component public class EvaluationWebMapper{public EvaluationCommands.ListEvaluations list(int p,int t,Long visita,Long cultivo,Integer tipo,Instant desde,Instant hasta){return new EvaluationCommands.ListEvaluations(new PageRequest<>(p,t,new EvaluationCommands.Filter(visita,cultivo,tipo,desde,hasta),null,null));}public EvaluationCommands.DryMatter dm(EvaluationRequests.DryMatter x){return x==null?null:new EvaluationCommands.DryMatter(x.porcentajeMateriaSeca(),x.numeroMuestras());}public EvaluationResponses.Summary response(EvaluationModels.Summary x){return new EvaluationResponses.Summary(x.evaluacionAgronomicaId(),x.visitaTecnicaId(),x.parcelaCultivoId(),x.tipoEvaluacionId(),x.codigoTipoEvaluacion(),x.tipoEvaluacion(),x.fechaHora(),x.resultado(),x.observacion(),x.porcentajeMateriaSeca(),x.numeroMuestras(),x.predioId(),x.codigoPredio(),x.predio());}public EvaluationResponses.Detail response(EvaluationModels.Detail x){return new EvaluationResponses.Detail(response(x.evaluacion()),x.parcelaId(),x.codigoParcela(),x.parcela(),x.variedad(),x.archivos().stream().map(f->new EvaluationResponses.File(f.archivoId(),f.nombreOriginal(),f.mimeType(),f.tamanoBytes(),f.secureUrl(),f.categoria(),f.origenCaptura(),f.fechaCarga())).toList());}}
